-- Rebuild the procurement plan from the authoritative Tranche A + B selected (2).xlsx workbook.
-- Empty source cells are deliberately stored as NULL. Batch 8 is Tranche A; batch 9 is Tranche B.
-- Procurement rows are linked through project_id to an actual subproject, never to the programme root.

ALTER TABLE procurement_records
    MODIFY COLUMN sub_project_lot_id VARCHAR(64) NULL,
    MODIFY COLUMN purchase_status VARCHAR(255) NULL,
    ADD COLUMN IF NOT EXISTS promotor_name VARCHAR(500) NULL AFTER oblast_id,
    ADD COLUMN IF NOT EXISTS subproject_name_uk TEXT NULL AFTER promotor_name,
    ADD COLUMN IF NOT EXISTS subproject_name_en TEXT NULL AFTER subproject_name_uk,
    ADD COLUMN IF NOT EXISTS sp_id VARCHAR(100) NULL AFTER sub_project_id,
    ADD COLUMN IF NOT EXISTS source_contract_type VARCHAR(255) NULL AFTER sp_id,
    ADD COLUMN IF NOT EXISTS source_type VARCHAR(64) NULL AFTER source_contract_type,
    ADD COLUMN IF NOT EXISTS procurement_id VARCHAR(128) NULL AFTER source_type,
    ADD COLUMN IF NOT EXISTS subproject_total_cost_uah DECIMAL(18,2) NULL AFTER procurement_id,
    ADD COLUMN IF NOT EXISTS subproject_eib_financing_uah DECIMAL(18,2) NULL AFTER subproject_total_cost_uah,
    ADD COLUMN IF NOT EXISTS subproject_local_financing_uah DECIMAL(18,2) NULL AFTER subproject_eib_financing_uah,
    ADD COLUMN IF NOT EXISTS estimated_total_eur DECIMAL(18,4) NULL AFTER subproject_local_financing_uah,
    ADD COLUMN IF NOT EXISTS estimated_total_uah DECIMAL(18,2) NULL AFTER estimated_total_eur,
    ADD COLUMN IF NOT EXISTS estimated_eib_eur DECIMAL(18,4) NULL AFTER estimated_total_uah,
    ADD COLUMN IF NOT EXISTS estimated_eib_uah DECIMAL(18,2) NULL AFTER estimated_eib_eur,
    ADD COLUMN IF NOT EXISTS estimated_local_eur DECIMAL(18,4) NULL AFTER estimated_eib_uah,
    ADD COLUMN IF NOT EXISTS estimated_local_uah DECIMAL(18,2) NULL AFTER estimated_local_eur,
    ADD COLUMN IF NOT EXISTS published_in_ojeu VARCHAR(64) NULL AFTER tender_document_type,
    ADD COLUMN IF NOT EXISTS local_financing_pct DECIMAL(14,10) NULL AFTER purchase_status,
    ADD COLUMN IF NOT EXISTS source_status_code VARCHAR(64) NULL AFTER local_financing_pct;

CREATE TEMPORARY TABLE procurement_import_stage (
    record_number INT NOT NULL, batch_id INT NOT NULL, oblast_id VARCHAR(32) NOT NULL,
    promotor_name VARCHAR(500) NULL, subproject_name_uk TEXT NULL, subproject_name_en TEXT NULL,
    subproject_id VARCHAR(100) NOT NULL, sp_id VARCHAR(100) NULL, source_contract_type VARCHAR(255) NULL,
    source_type VARCHAR(64) NULL, procurement_id VARCHAR(128) NULL, subproject_total_cost_uah DECIMAL(18,2) NULL,
    subproject_eib_financing_uah DECIMAL(18,2) NULL, subproject_local_financing_uah DECIMAL(18,2) NULL,
    estimated_total_eur DECIMAL(18,4) NULL, estimated_total_uah DECIMAL(18,2) NULL,
    estimated_eib_eur DECIMAL(18,4) NULL, estimated_eib_uah DECIMAL(18,2) NULL,
    estimated_local_eur DECIMAL(18,4) NULL, estimated_local_uah DECIMAL(18,2) NULL,
    procurement_method VARCHAR(255) NULL, tender_document_type VARCHAR(255) NULL, published_in_ojeu VARCHAR(64) NULL,
    estimated_prozorro_date DATE NULL, estimated_bid_submission_date DATE NULL, estimated_contract_date DATE NULL,
    estimated_contract_end_date DATE NULL, purchase_status VARCHAR(255) NULL, local_financing_pct DECIMAL(14,10) NULL,
    comments TEXT NULL, source_status_code VARCHAR(64) NULL
);

