-- Add only absent canonical subprojects. Existing hierarchy and project records stay intact.
INSERT INTO projects (
    uuid, project_type, tranche_number, parent_project_id, name, site_name, site_number,
    description, address, region, city, latitude, longitude, status, sector, construction_type,
    budget_planned, currency, created_by
)
SELECT UUID(), 'subproject', s.batch_id,
    (SELECT id FROM projects WHERE uuid = '42611a16-f360-5f8b-87a8-00680318888b' LIMIT 1),
    COALESCE(s.subproject_name_uk, s.subproject_name_en, s.subproject_id),
    s.subproject_id, s.subproject_id, NULL, NULL,
    CASE s.oblast_id
    WHEN 'CH' THEN 'Чернігівська область' WHEN 'CK' THEN 'Черкаська область'
    WHEN 'CV' THEN 'Чернівецька область' WHEN 'DP' THEN 'Дніпропетровська область'
    WHEN 'IF' THEN 'Івано-Франківська область' WHEN 'KH' THEN 'Харківська область'
    WHEN 'KM' THEN 'Хмельницька область' WHEN 'KR' THEN 'Кіровоградська область'
    WHEN 'KS' THEN 'Херсонська область' WHEN 'KV' THEN 'Київська область'
    WHEN 'LV' THEN 'Львівська область' WHEN 'MY' THEN 'Миколаївська область'
    WHEN 'OD' THEN 'Одеська область' WHEN 'PL' THEN 'Полтавська область'
    WHEN 'RV' THEN 'Рівненська область' WHEN 'SM' THEN 'Сумська область'
    WHEN 'TR' THEN 'Тернопільська область' WHEN 'VN' THEN 'Вінницька область'
    WHEN 'ZH' THEN 'Житомирська область' WHEN 'ZK' THEN 'Закарпатська область'
    WHEN 'ZP' THEN 'Запорізька область' ELSE NULL END, NULL, NULL, NULL, 'planned', NULL, NULL,
    ROUND(COALESCE(s.subproject_total_cost_uah, 0)), 'UAH',
    (SELECT id FROM users WHERE username = 'admin' LIMIT 1)
FROM procurement_import_stage s
WHERE NOT EXISTS (
    SELECT 1 FROM projects p WHERE p.project_type = 'subproject' AND p.site_number = s.subproject_id
);

DELETE FROM procurement_records;

INSERT INTO procurement_records (
    record_number, batch_id, oblast_name, oblast_id, promotor_name,
    sub_project_id, sub_project_lot_id, sp_id, source_contract_type, source_type, procurement_id,
    subproject_total_cost_uah, subproject_eib_financing_uah, subproject_local_financing_uah,
    estimated_total_eur, estimated_total_uah, estimated_eib_eur, estimated_eib_uah,
    estimated_local_eur, estimated_local_uah, procurement_method, tender_document_type,
    published_in_ojeu, estimated_prozorro_date, estimated_bid_submission_date,
    estimated_contract_date, estimated_contract_end_date, purchase_status, local_financing_pct,
    comments, source_status_code, project_id, contract_type
)
SELECT s.record_number, s.batch_id, CASE s.oblast_id
    WHEN 'CH' THEN 'Чернігівська область' WHEN 'CK' THEN 'Черкаська область'
    WHEN 'CV' THEN 'Чернівецька область' WHEN 'DP' THEN 'Дніпропетровська область'
    WHEN 'IF' THEN 'Івано-Франківська область' WHEN 'KH' THEN 'Харківська область'
    WHEN 'KM' THEN 'Хмельницька область' WHEN 'KR' THEN 'Кіровоградська область'
    WHEN 'KS' THEN 'Херсонська область' WHEN 'KV' THEN 'Київська область'
    WHEN 'LV' THEN 'Львівська область' WHEN 'MY' THEN 'Миколаївська область'
    WHEN 'OD' THEN 'Одеська область' WHEN 'PL' THEN 'Полтавська область'
    WHEN 'RV' THEN 'Рівненська область' WHEN 'SM' THEN 'Сумська область'
    WHEN 'TR' THEN 'Тернопільська область' WHEN 'VN' THEN 'Вінницька область'
    WHEN 'ZH' THEN 'Житомирська область' WHEN 'ZK' THEN 'Закарпатська область'
    WHEN 'ZP' THEN 'Запорізька область' ELSE NULL END, s.oblast_id, s.promotor_name,
    s.subproject_id, NULL, s.sp_id, s.source_contract_type, s.source_type, s.procurement_id,
    s.subproject_total_cost_uah, s.subproject_eib_financing_uah, s.subproject_local_financing_uah,
    s.estimated_total_eur, s.estimated_total_uah, s.estimated_eib_eur, s.estimated_eib_uah,
    s.estimated_local_eur, s.estimated_local_uah, s.procurement_method, s.tender_document_type,
    s.published_in_ojeu, s.estimated_prozorro_date, s.estimated_bid_submission_date,
    s.estimated_contract_date, s.estimated_contract_end_date, s.purchase_status, s.local_financing_pct,
    s.comments, s.source_status_code,
    (SELECT p.id FROM projects p WHERE p.project_type = 'subproject' AND p.site_number = s.subproject_id LIMIT 1),
    COALESCE(s.source_contract_type, 'works')
FROM procurement_import_stage s;

DROP TEMPORARY TABLE procurement_import_stage;
